import React, { useEffect, useRef, useState } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';
import * as turf from '@turf/turf'; // ✅ Add this package to use Turf.js for buffering
import { getGeojsonFile, areas } from '../config';
import './DQT.css';

mapboxgl.accessToken = 'pk.eyJ1Ijoib3R0b3R1aGt1bmVuIiwiYSI6ImNseG41dW9vaDAwNzQycXNleWI1MmowbHcifQ.1ZMRPeOQ7z9GRzKILnFNAQ';

const DQT = () => {
  const mapContainerRef = useRef(null);
  const mapRef = useRef(null);
  const observerRef = useRef(null);
  const [airspaceData, setAirspaceData] = useState(null);
  const [airportGeojson, setAirportGeojson] = useState(null);
  const [showAirports, setShowAirports] = useState(true);
  const [firGeojson, setFirGeojson] = useState(null);
  const [showBuffer, setShowBuffer] = useState(false);
  const [bufferDistance, setBufferDistance] = useState(3); // Default 3 NM
  const [customGeojson, setCustomGeojson] = useState(null);
  const [uploadError, setUploadError] = useState(null);

  document.title = "V-LARA DQT";

  useEffect(() => {
    fetch('data/airports.geojson')
      .then((res) => res.json())
      .then((data) => setAirportGeojson(data))
      .catch((err) => console.error('Failed to load airport data:', err));

    fetch('data/firs.json')
      .then((res) => res.json())
      .then((data) => setFirGeojson(data))
      .catch((err) => console.error('Failed to load FIR data:', err));
  }, []);

  useEffect(() => {
    if (!mapRef.current) return;
    const map = mapRef.current;

    if (map.getLayer('airports-layer')) {
      map.setLayoutProperty('airports-layer', 'visibility', showAirports ? 'visible' : 'none');
    }
  }, [showAirports]);

  const updateBufferLayer = (baseFeatures) => {
    const map = mapRef.current;
    if (!map || !map.getSource('fbz-buffer')) return;

    const buffered = {
      type: "FeatureCollection",
      features: baseFeatures.map(f => {
        try {
          return turf.buffer(f, bufferDistance, { units: 'nauticalmiles' });
        } catch {
          return null;
        }
      }).filter(Boolean)
    };

    map.getSource('fbz-buffer').setData(buffered);
  };

  const toggleBufferLayer = (features) => {
    const map = mapRef.current;
    if (!map) return;

    if (showBuffer && !map.getSource('fbz-buffer')) {
      map.addSource('fbz-buffer', {
        type: 'geojson',
        data: turf.featureCollection([])
      });

      map.addLayer({
        id: 'fbz-buffer-layer',
        type: 'line',
        source: 'fbz-buffer',
        layout: {},
        paint: {
          'line-color': '#222',
          'line-width': 0.6,
          'line-dasharray': [2, 4]
        }
      });
    }

    if (showBuffer) {
      const coloredFeatures = features.map(f => ({
        ...f,
        properties: {
          ...f.properties,
          color: f.properties.status === 'active' ? 'red' :
                 f.properties.status === 'reserved' ? '#0492c2' :
                 f.properties.status === 'pending' ? 'orange' : 'green'
        }
      }));
      updateBufferLayer(coloredFeatures);
    } else {
      if (map.getLayer('fbz-buffer-layer')) map.removeLayer('fbz-buffer-layer');
      if (map.getSource('fbz-buffer')) map.removeSource('fbz-buffer');
    }
  };

  const handleGeojsonUpload = (event) => {
    const file = event.target.files[0];
    if (!file) return;
  
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const parsed = JSON.parse(e.target.result);
        const features = parsed.features;
  
        if (!parsed || parsed.type !== 'FeatureCollection' || !Array.isArray(features)) {
          throw new Error("Invalid GeoJSON format: Not a FeatureCollection.");
        }
  
        for (let i = 0; i < features.length; i++) {
          const f = features[i];
          const props = f.properties || {};
          const missing = [];
  
          // Required fields: name and type must exist (even if empty)
          if (!props.hasOwnProperty('name')) missing.push('name');
          if (!props.hasOwnProperty('type')) missing.push('type');
  
          // Required fields: upperFL and lowerFL must exist, be integers, and in range
          if (!props.hasOwnProperty('upperFL')) {
            missing.push('upperFL');
          } else {
            const upper = props.upperFL;
            if (!Number.isInteger(upper) || upper < 0 || upper > 999) {
              throw new Error(`Feature ${i + 1}: upperFL must be an integer between 0 and 999`);
            }
          }
  
          if (!props.hasOwnProperty('lowerFL')) {
            missing.push('lowerFL');
          } else {
            const lower = props.lowerFL;
            if (!Number.isInteger(lower) || lower < 0 || lower > 999) {
              throw new Error(`Feature ${i + 1}: lowerFL must be an integer between 0 and 999`);
            }
          }
  
          if (missing.length > 0) {
            throw new Error(`Feature ${i + 1} missing required properties: ${missing.join(', ')}`);
          }
  
          // Optional: mustBeBookedWith must be an array if it exists
          if ('mustBeBookedWith' in props && !Array.isArray(props.mustBeBookedWith)) {
            throw new Error(`Feature ${i + 1}: 'mustBeBookedWith' must be an array`);
          }
  
          // Optional: activationLimits must be an array if it exists
          if ('activationLimits' in props && !Array.isArray(props.activationLimits)) {
            throw new Error(`Feature ${i + 1}: 'activationLimits' must be an array`);
          }
        }
  
        // All checks passed
        setUploadError('');
        setCustomGeojson(parsed);
      } catch (err) {
        console.error(err);
        setUploadError(err.message);
        setCustomGeojson(null);
      }
    };
  
    reader.readAsText(file);
  };  
  
  useEffect(() => {
    if (!mapRef.current || !customGeojson) return;
  
    const map = mapRef.current;
  
    if (map.getSource('custom-geojson')) {
      map.getSource('custom-geojson').setData(customGeojson);
    } else {
      map.addSource('custom-geojson', {
        type: 'geojson',
        data: customGeojson
      });
  
      map.addLayer({
        id: 'custom-fill',
        type: 'fill',
        source: 'custom-geojson',
        paint: {
          'fill-color': 'rgba(200, 0, 0, 0.1)',
          'fill-outline-color': 'red'
        }
      });
  
      map.addLayer({
        id: 'custom-outline',
        type: 'line',
        source: 'custom-geojson',
        paint: {
          'line-color': 'red',
          'line-width': 1
        }
      });
  
      map.addLayer({
        id: 'custom-labels',
        type: 'symbol',
        source: 'custom-geojson',
        layout: {
          'text-field': ['get', 'name'],
          'text-size': 9,
          'text-anchor': 'center',
          'text-font': ['Open Sans Bold', 'Arial Unicode MS Bold']
        },
        paint: {
          'text-color': 'black',
          'text-halo-color': 'white',
          'text-halo-width': 1
        }
      });
    }
  }, [customGeojson]);  

  useEffect(() => {
    const fetchData = async () => {
      try {
        const locations = areas.filter(area => area.value !== "eacc").map(area => area.value);
        const data = await Promise.all(locations.map(loc =>
          fetch(getGeojsonFile(loc)).then(res => res.json())
        ));
        setAirspaceData({
          type: "FeatureCollection",
          features: data.flatMap(f => f.features)
        });
      } catch (error) {
        console.error("Error loading GeoJSON:", error);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (!airspaceData) return;

    const map = new mapboxgl.Map({
      container: mapContainerRef.current,
      style: 'mapbox://styles/ottotuhkunen/cm8g2jfyj00yv01sa0tvx4vof',
      center: [18, 58],
      zoom: 3
    });

    mapRef.current = map;

    const addLayers = () => {
      // Add Airspaces
      map.addSource('airspaces', {
        type: 'geojson',
        data: airspaceData
      });

      map.addLayer({
        id: 'airspace-outline',
        type: 'line',
        source: 'airspaces',
        paint: {
          'line-color': '#c98fc1',
          'line-width': 1
        }
      });

      map.addLayer({
        id: 'airspace-fill',
        type: 'fill',
        source: 'airspaces',
        paint: {
          'fill-color': 'transparent'
        }
      });

      map.addLayer({
        id: 'airspace-labels',
        type: 'symbol',
        source: 'airspaces',
        layout: {
          'text-field': ['get', 'name'],
          'text-size': 9,
          'text-anchor': 'center',
          'text-font': ['Open Sans Bold', 'Arial Unicode MS Bold'],
        },
        paint: {
          'text-color': '#c98fc1',
          'text-halo-color': 'white',
          'text-halo-width': 1
        },
        minzoom: 4
      });

      // Add FIRs
      if (firGeojson) {
        map.addSource('firs', { type: 'geojson', data: firGeojson });

        map.addLayer({
          id: 'firs-outline',
          type: 'line',
          source: 'firs',
          paint: {
            'line-color': 'green',
            'line-width': 1.2
          }
        });
      }
    };

    const setupUI = () => {

      map.on('click', 'airspace-fill', e => {
        const features = map.queryRenderedFeatures(e.point, { layers: ['airspace-fill'] });
        const valid = [...new Map(
          features.filter(f => f.properties.name).map(f => [f.properties.name, f])
        ).values()];
        if (!valid.length) return;

        const html = valid.map(f => {
          const p = f.properties;
          const lines = [
            `<strong class="dqt-popup-title">${p.name}</strong>`,
            `${p.lowerFL || 'SFC'} - ${ p.upperFL || 'UNL'}`,
            `${p.type || 'NIL'}`
          ];
          if (p.mustBeBookedWith) {
            try {
              const group = JSON.parse(p.mustBeBookedWith);
              if (Array.isArray(group)) lines.push(`<em>Booked with:</em> ${group.join(', ')}`);
            } catch {}
          }
          return `<div class="dqt-popup">${lines.join('<br/>')}</div>`;
        }).join('<hr class="dqt-popup-hr"/>');

        new mapboxgl.Popup().setLngLat(e.lngLat).setHTML(html).addTo(map);
      });

      map.on('mousemove', 'airspace-fill', e => {
        const features = map.queryRenderedFeatures(e.point, { layers: ['airspace-fill'] });
        const hasName = features.some(f => f.properties.name);
        map.getCanvas().style.cursor = hasName ? 'pointer' : '';
      });
    };

    observerRef.current = new ResizeObserver(() => map.resize());
    observerRef.current.observe(mapContainerRef.current);

    map.dragRotate.disable();
    map.touchZoomRotate.disableRotation();

    map.on('load', async () => {
      addLayers();
      setupUI();

      if (airportGeojson) {
        map.loadImage('/images/airport.png', (err, image) => {
          if (err || !image) return console.error('Failed to load icon', err);
          if (!map.hasImage('airport-icon')) map.addImage('airport-icon', image, { sdf: true });

          map.addSource('airports', { type: 'geojson', data: airportGeojson });

          map.addLayer({
            id: 'airports-layer',
            type: 'symbol',
            source: 'airports',
            layout: {
              'icon-image': 'airport-icon',
              'icon-size': 0.3,
              'text-field': ['get', 'icao_code'],
              'text-size': 9,
              'text-offset': [0.8, 0],
              'text-anchor': 'left',
              'text-font': ['Open Sans Bold', 'Arial Unicode MS Bold'],
            },
            paint: {
              'icon-color': '#3b5e97',
              'text-color': '#3b5e97',
              'text-halo-color': '#fff',
              'text-halo-width': 1
            }
          });
        });
      }
    });

    return () => {
      if (observerRef.current) observerRef.current.disconnect();
      map.remove();
    };
  }, [airspaceData, firGeojson]);

  useEffect(() => {
    if (!mapRef.current || !airspaceData) return;
    toggleBufferLayer(airspaceData.features);
  }, [showBuffer, bufferDistance]);

  return (
    <div style={{ width: '100%', height: '100%', position: 'relative' }}>
      <div className='dqt-top-menu'>
        <button onClick={() => setShowAirports(prev => !prev)} className='arp-toggle-button'>
          ARP
        </button>

        {/* FBZ Toggle */}
        <button onClick={() => setShowBuffer(prev => !prev)} className='fbz-toggle-button'>
          FBZ
        </button>

        <select
          value={bufferDistance}
          onChange={(e) => setBufferDistance(parseFloat(e.target.value))}
          className='fbz-distance-select'
        >
          <option value={2.5}>2.5 NM</option>
          <option value={3}>3 NM</option>
          <option value={5}>5 NM</option>
        </select>
        <input
          type="file"
          accept=".geojson,application/geo+json,application/json"
          onChange={(e) => handleGeojsonUpload(e)}
          className="geojson-upload"
        />
      </div>
      {uploadError ? (
        <div className="geojson-error">{uploadError}</div>
      ) : uploadError === '' && (
        <div className="geojson-valid">Airspace format is valid</div>
      )}
      <div ref={mapContainerRef} className="map-container" />
    </div>
  );
};

export default DQT;
